// connection: its permit, the recorded outcome and its effect.
func (q *Queries) ReceiptOfCorrelation(ctx context.Context, orgID ids.OrgID, transactionID ids.UUID, connectionID *ids.UUID) (ReceiptOfCorrelationRow, error) {
	row := q.db.QueryRow(ctx, receiptOfCorrelation, orgID, transactionID, connectionID)
	var i ReceiptOfCorrelationRow
	err := row.Scan(
		&i.PermitID,
		&i.PermitState,
		&i.Outcome,
		&i.EffectState,
		&i.EffectLevelRequired,
		&i.EffectLevelAchieved,
		&i.DefinitionDigest,
	)
	return i, err
}

const recordTestTokenMint = `-- name: RecordTestTokenMint :execrows
UPDATE pc.connection_tests
SET tokens_attempt = $1::integer
WHERE org_id = $2 AND id = $3 AND kind = 'target_verifier' AND state = 'RUNNING'
  AND coalesce(tokens_attempt, 0) < $1::integer
`

// RecordTestTokenMint records a running target_verifier test's token mint
// for its lease attempt: at most one mint per attempt (HR-188's exception).
func (q *Queries) RecordTestTokenMint(ctx context.Context, attempt int32, orgID ids.OrgID, iD ids.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, recordTestTokenMint, attempt, orgID, iD)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const releaseExpiredLeases = `-- name: ReleaseExpiredLeases :many
UPDATE pc.verifications
SET state = CASE WHEN deadline_at <= now() OR (purpose = 'connection_test' AND attempts >= $1::integer)
                      OR (purpose = 'org_scan' AND attempts >= 3)
                      OR (purpose IN ('credential_rotation_test', 'credential_rotation_confirm') AND attempts >= 3)
                 THEN 'EXPIRED' ELSE 'PENDING' END,
    finished_at = CASE WHEN deadline_at <= now() OR (purpose = 'connection_test' AND attempts >= $1::integer)
                            OR (purpose = 'org_scan' AND attempts >= 3)
                            OR (purpose IN ('credential_rotation_test', 'credential_rotation_confirm') AND attempts >= 3)
                       THEN now() END,
    lease_hash = NULL, leased_by = NULL, leased_at = NULL, lease_expires_at = NULL
WHERE org_id = $2 AND state = 'LEASED' AND lease_expires_at < now()
RETURNING id, state, transaction_id
`

type ReleaseExpiredLeasesRow struct {
	ID            ids.UUID
	State         string
	TransactionID *ids.UUID
}

// ReleaseExpiredLeases returns leases nobody reported in time to PENDING,
// or ends them when the task's deadline passed too, when it is a
// connection test leased max_test_attempts times (HR-188), or when it is an
// organization scan leased three times, each a whole scan's worth of the
// installation's API quota (HR-209), or a rotation test or confirmation
// leased three times (G0 M20 S20c).
func (q *Queries) ReleaseExpiredLeases(ctx context.Context, maxTestAttempts int32, orgID ids.OrgID) ([]ReleaseExpiredLeasesRow, error) {
	rows, err := q.db.Query(ctx, releaseExpiredLeases, maxTestAttempts, orgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReleaseExpiredLeasesRow{}
	for rows.Next() {
		var i ReleaseExpiredLeasesRow
		if err := rows.Scan(&i.ID, &i.State, &i.TransactionID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const retryVerification = `-- name: RetryVerification :exec
UPDATE pc.verifications
SET state = 'PENDING', next_at = now() + make_interval(secs => $1::float8), lease_hash = NULL,
    leased_by = NULL, leased_at = NULL, lease_expires_at = NULL
WHERE org_id = $2 AND id = $3 AND state = 'LEASED'
`

func (q *Queries) RetryVerification(ctx context.Context, delaySeconds float64, orgID ids.OrgID, iD ids.UUID) error {
	_, err := q.db.Exec(ctx, retryVerification, delaySeconds, orgID, iD)
	return err
}

const scheduleConsequenceVerification = `-- name: ScheduleConsequenceVerification :exec
INSERT INTO pc.verifications (org_id, id, purpose, transaction_id, connection_id, operation, request, next_at, deadline_at,
                              definition_digest, basis_at)
VALUES ($1, $2, 'consequence', $3,
        (SELECT t.connection_id FROM pc.transactions t WHERE t.org_id = $1 AND t.id = $3), $4,
        $5, now() + make_interval(secs => $6::float8),
        now() + make_interval(secs => $7::float8), $8, now())
`

type ScheduleConsequenceVerificationParams struct {
	OrgID            ids.OrgID
	ID               ids.UUID
	TransactionID    *ids.UUID
	Operation        string
	Request          []byte
	DelaySeconds     float64
	WithinSeconds    float64
	DefinitionDigest *string
}

// ScheduleConsequenceVerification creates a consequence's verification
// task, with the definition it verifies and the start of its window.
func (q *Queries) ScheduleConsequenceVerification(ctx context.Context, arg ScheduleConsequenceVerificationParams) error {
	_, err := q.db.Exec(ctx, scheduleConsequenceVerification,
		arg.OrgID,
		arg.ID,
		arg.TransactionID,
		arg.Operation,
		arg.Request,
		arg.DelaySeconds,
		arg.WithinSeconds,
		arg.DefinitionDigest,
	)
	return err
}

